SELECT COUNT(*) FROM users as u, comments as c, posts as p, votes as v WHERE u.Id = c.UserId AND p.Id = c.PostId AND u.Id = v.UserId AND u.Reputation<=270 AND u.Views>=0 AND u.Views<=51 AND u.DownVotes>=0 AND c.Score=0 AND c.CreationDate>='2010-08-02 20:27:48'::timestamp AND c.CreationDate<='2014-09-10 16:09:23'::timestamp AND p.PostTypeId=1 AND p.Score=4 AND p.ViewCount<=4937;